package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        Complex c = new Complex(1.0, 2.0);
        assertTrue("Should return true for the same instance", c.equals(c));
    }

    @Test
    public void testEquals_Null() {
        Complex c = new Complex(1.0, 2.0);
        assertFalse("Should return false when compared with null", c.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        Complex c = new Complex(1.0, 2.0);
        assertFalse("Should return false when compared with a different object type", c.equals("not a complex number"));
    }

    @Test
    public void testEquals_EqualValues() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.0);
        assertTrue("Should return true for identical real and imaginary values", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentReal() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.1, 2.0);
        assertFalse("Should return false for different real parts", c1.equals(c2));
    }

    @Test
    public void testEquals_DifferentImaginary() {
        Complex c1 = new Complex(1.0, 2.0);
        Complex c2 = new Complex(1.0, 2.1);
        assertFalse("Should return false for different imaginary parts", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_BothNaN() {
        // Double.NaN is handled by isNaN() logic in the method
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(Double.NaN, Double.NaN);
        assertTrue("Should return true if both are NaN", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_OneNaN() {
        Complex c1 = new Complex(Double.NaN, Double.NaN);
        Complex c2 = new Complex(1.0, 2.0);
        assertFalse("Should return false if only one is NaN", c1.equals(c2));
    }

    @Test
    public void testEquals_NaN_RealNaN() {
        // Testing the branch: if (rhs.isNaN()) { ret = this.isNaN(); }
        // If rhs is NaN, the result depends entirely on whether 'this' is NaN.
        Complex c1 = new Complex(Double.NaN, 2.0);
        Complex c2 = new Complex(Double.NaN, 2.0);
        // Note: In Apache Commons Math, isNaN() checks if either real or imaginary is NaN.
        assertTrue("Should return true if both are NaN (via isNaN check)", c1.equals(c2));

        Complex c3 = new Complex(1.0, 2.0);
        assertFalse("Should return false if rhs is NaN but this is not", c3.equals(c2));
    }

    @Test
    public void testEquals_EdgeCases_Zero() {
        // Testing bit-level equality (0.0 vs -0.0)
        // Double.doubleToRawLongBits distinguishes between +0.0 and -0.0
        Complex c1 = new Complex(0.0, 0.0);
        Complex c2 = new Complex(-0.0, -0.0);
        assertFalse("Should return false for +0.0 and -0.0 due to raw long bits comparison", c1.equals(c2));
    }
}
